-- Sample avatar photo updates for TMS_CANDIDATES
-- Fixed to avoid ORA-01704 by chunking Base64 into small literals.
-- Uses APEX_WEB_SERVICE.CLOBBASE642BLOB to populate PHOTO_BLOB.

SET DEFINE OFF;

UPDATE tms_candidates
   SET photo_blob = apex_web_service.clobbase642blob(
                    TO_CLOB(q'[]')
               || TO_CLOB(q'[]')
               || TO_CLOB(q'[]')
               || TO_CLOB(q'[]')
               || TO_CLOB(q'[]')
               || TO_CLOB(q'[]')
               || TO_CLOB(q'[]')
               || TO_CLOB(q'[]')
               || TO_CLOB(q'[]')),
       photo_mime_type = 'image/png'
 WHERE candidate_id = 1;

